1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type ScenarioResult = {
41	  results: unknown[];
42	};
43	
44	const PROCESSING_FEE = 5;
45	
46	type ItemTypeSpec = {
47	  basePremium: number;
48	  insuranceValue: number;
49	};
50	
51	const ITEM_CATALOGUE: Record<string, ItemTypeSpec> = {
52	  sword: { basePremium: 100, insuranceValue: 1000 },
53	  amulet: { basePremium: 60, insuranceValue: 600 },
54	  staff: { basePremium: 80, insuranceValue: 800 },
55	  potion: { basePremium: 40, insuranceValue: 400 },
56	  rune: { basePremium: 25, insuranceValue: 250 },
57	  moonstone: { basePremium: 25, insuranceValue: 250 },
58	};
59	
60	// Most money figures in a policy are "some value, totalled over the items".
61	const sumOver = (items: Item[], valueOf: (item: Item) => number): number =>
62	  items.reduce((total, item) => total + valueOf(item), 0);
63	
64	const catalogueEntryFor = (item: Item): ItemTypeSpec => {
65	  const spec = ITEM_CATALOGUE[item.type];
66	
67	  if (spec === undefined) {
68	    throw new Error(`unknown item type: ${item.type}`);
69	  }
70	
71	  return spec;
72	};
73	
74	const basePremiumOf = (item: Item): number =>
75	  catalogueEntryFor(item).basePremium;
76	
77	const insuranceValueOf = (item: Item): number =>
78	  catalogueEntryFor(item).insuranceValue;
79	
80	const BLOCK_SIZE = 3;
81	const BLOCK_BASE_PREMIUM = 60;
82	
83	const itemsGroupedByType = (items: Item[]): Item[][] => [
84	  ...items
85	    .reduce(
86	      (groupsByType, item) =>
87	        groupsByType.set(item.type, [
88	          ...(groupsByType.get(item.type) ?? []),
89	          item,
90	        ]),
91	      new Map<string, Item[]>(),
92	    )
93	    .values(),
94	];
95	
96	const formsABlock = (itemsAlike: Item[]): boolean =>
97	  itemsAlike.length === BLOCK_SIZE;
98	
99	const basePremiumOfItemsAlike = (itemsAlike: Item[]): number =>
100	  formsABlock(itemsAlike)
101	    ? BLOCK_BASE_PREMIUM
102	    : sumOver(itemsAlike, basePremiumOf);
103	
104	const totalBasePremiumOf = (items: Item[]): number =>
105	  itemsGroupedByType(items).reduce(
106	    (total, itemsAlike) => total + basePremiumOfItemsAlike(itemsAlike),
107	    0,
108	  );
109	
110	// The MHPCO rounds whichever way costs it least: premiums up, payouts down.
111	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
112	
113	const roundedDownInMHPCOsFavour = (payout: number): number =>
114	  Math.floor(payout);
115	
116	type Rule<Subject> = {
117	  appliesTo: (subject: Subject) => boolean;
118	  rate: number;
119	};
120	
121	const totalRateOf = <Subject,>(
122	  rules: Rule<Subject>[],
123	  subject: Subject,
124	): number =>
125	  rules.reduce(
126	    (rate, rule) => (rule.appliesTo(subject) ? rate + rule.rate : rate),
127	    0,
128	  );
129	
130	const CURSE_SURCHARGE_RATE = 0.5;
131	const HIGH_ENCHANTMENT_THRESHOLD = 5;
132	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
133	
134	const ITEM_SURCHARGE_RULES: Rule<Item>[] = [
135	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
136	  {
137	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
138	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
139	  },
140	];
141	
142	const itemSurchargeOf = (item: Item): number =>
143	  basePremiumOf(item) * totalRateOf(ITEM_SURCHARGE_RULES, item);
144	
145	const totalItemSurchargeOf = (items: Item[]): number =>
146	  sumOver(items, itemSurchargeOf);
147	
148	const LOYALTY_YEARS_THRESHOLD = 2;
149	const LOYALTY_DISCOUNT_RATE = -0.2;
150	
151	// Levied on every policy, follow-ups included — not only on a customer's first.
152	const INSURANCE_SURCHARGE_RATE = 0.1;
153	
154	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
155	
156	type PolicyContext = {
157	  customer: Customer;
158	  previousContracts: number;
159	};
160	
161	const POLICY_MODIFIER_RULES: Rule<PolicyContext>[] = [
162	  {
163	    appliesTo: ({ customer }) =>
164	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
165	    rate: LOYALTY_DISCOUNT_RATE,
166	  },
167	  {
168	    appliesTo: ({ previousContracts }) => previousContracts > 0,
169	    rate: FOLLOW_UP_DISCOUNT_RATE,
170	  },
171	];
172	
173	const totalPolicyModifierRateOf = (policy: PolicyContext): number =>
174	  INSURANCE_SURCHARGE_RATE + totalRateOf(POLICY_MODIFIER_RULES, policy);
175	
176	const quotePremium = (items: Item[], policy: PolicyContext): number => {
177	  const basePremium = totalBasePremiumOf(items);
178	
179	  return roundedUpInMHPCOsFavour(
180	    basePremium +
181	      totalItemSurchargeOf(items) +
182	      basePremium * totalPolicyModifierRateOf(policy) +
183	      PROCESSING_FEE,
184	  );
185	};
186	
187	const DEDUCTIBLE = 100;
188	const CAP_MULTIPLIER = 2;
189	
190	const insuranceSumOf = (items: Item[]): number =>
191	  sumOver(items, insuranceValueOf);
192	
193	const payoutCapOf = (items: Item[]): number =>
194	  CAP_MULTIPLIER * insuranceSumOf(items);
195	
196	const HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
197	const HALVED_REIMBURSEMENT_RATE = 0.5;
198	const FULL_REIMBURSEMENT_RATE = 1;
199	
200	const reimbursementRateFor = (item: Item): number =>
201	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
202	    ? HALVED_REIMBURSEMENT_RATE
203	    : FULL_REIMBURSEMENT_RATE;
204	
205	const payoutForDamage = (damage: Damage, item: Item): number =>
206	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;
207	
208	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
209	
210	type ClaimResult = {
211	  payout: number;
212	  remainingCap: number;
213	};
214	
215	// Each damage entry is settled against a distinct insured item, so a policy
216	// covering one sword cannot pay out for two damaged swords.
217	type Settlement = {
218	  total: number;
219	  unclaimedItems: Item[];
220	};
221	
222	const NOT_FOUND = -1;
223	
224	// A loss of negative value is not a loss; the MHPCO will not be talked into
225	// treating one as a claim.
226	const rejectingNonLosses = (damage: Damage): Damage => {
227	  if (damage.amount < 0) {
228	    throw new Error(`negative damage amount: ${damage.amount}`);
229	  }
230	
231	  return damage;
232	};
233	
234	// The policy must still have an unclaimed item of the damaged type to settle
235	// against. Answers with that item's position, so the caller can both pay for
236	// it and strike it off.
237	const claimedItemIndexFor = (
238	  damage: Damage,
239	  unclaimedItems: Item[],
240	): number => {
241	  const claimedAgainst = unclaimedItems.findIndex(
242	    (item) => item.type === damage.itemType,
243	  );
244	
245	  if (claimedAgainst === NOT_FOUND) {
246	    throw new Error(`damaged item not insured: ${damage.itemType}`);
247	  }
248	
249	  return claimedAgainst;
250	};
251	
252	const settleDamage = (
253	  { total, unclaimedItems }: Settlement,
254	  incoming: Damage,
255	): Settlement => {
256	  const damage = rejectingNonLosses(incoming);
257	  const claimedAgainst = claimedItemIndexFor(damage, unclaimedItems);
258	
259	  return {
260	    total: total + payoutForDamage(damage, unclaimedItems[claimedAgainst]),
261	    unclaimedItems: unclaimedItems.filter(
262	      (_, index) => index !== claimedAgainst,
263	    ),
264	  };
265	};
266	
267	const totalPayoutFor = (damages: Damage[], insuredItems: Item[]): number =>
268	  damages.reduce(settleDamage, { total: 0, unclaimedItems: insuredItems })
269	    .total;
270	
271	// A claim never pays out more than the policy has left; whatever it does pay
272	// depletes the cap by exactly that much.
273	const drawnAgainstCap = (
274	  desiredPayout: number,
275	  remainingCap: number,
276	): ClaimResult => {
277	  const payout = roundedDownInMHPCOsFavour(
278	    Math.min(desiredPayout, remainingCap),
279	  );
280	
281	  return { payout, remainingCap: remainingCap - payout };
282	};
283	
284	const settleClaim = (incident: Incident, policy: IssuedPolicy): ClaimResult =>
285	  drawnAgainstCap(
286	    totalPayoutFor(incident.damages, policy.insuredItems),
287	    policy.remainingCap,
288	  );
289	
290	// A policy, once quoted, is referred to by later claim steps via its step index.
291	// Its cap depletes as claims are paid out against it.
292	type IssuedPolicy = {
293	  insuredItems: Item[];
294	  remainingCap: number;
295	};
296	
297	// Everything a step needs to know about the steps that came before it.
298	// Policies are keyed by the index of the quote step that issued them, which is
299	// how a claim step refers to them.
300	type ScenarioHistory = {
301	  issuedPolicies: Map<number, IssuedPolicy>;
302	  results: unknown[];
303	};
304	
305	const EMPTY_HISTORY: ScenarioHistory = {
306	  issuedPolicies: new Map(),
307	  results: [],
308	};
309	
310	// Every step both records a result and leaves exactly one policy changed:
311	// a quote issues one, a claim depletes the cap of the one it draws against.
312	type StepOutcome = {
313	  policyIndex: number;
314	  policy: IssuedPolicy;
315	  result: unknown;
316	};
317	
318	const withStepRecorded = (
319	  history: ScenarioHistory,
320	  { policyIndex, policy, result }: StepOutcome,
321	): ScenarioHistory => ({
322	  issuedPolicies: new Map(history.issuedPolicies).set(policyIndex, policy),
323	  results: [...history.results, result],
324	});
325	
326	const takeQuoteStep = (
327	  step: QuoteStep,
328	  stepIndex: number,
329	  history: ScenarioHistory,
330	  customer: Customer,
331	): ScenarioHistory =>
332	  withStepRecorded(history, {
333	    policyIndex: stepIndex,
334	    policy: {
335	      insuredItems: step.items,
336	      remainingCap: payoutCapOf(step.items),
337	    },
338	    result: {
339	      premium: quotePremium(step.items, {
340	        customer,
341	        previousContracts: history.issuedPolicies.size,
342	      }),
343	    },
344	  });
345	
346	const issuedPolicyFor = (
347	  step: ClaimStep,
348	  issuedPolicies: Map<number, IssuedPolicy>,
349	): IssuedPolicy => {
350	  const policy = issuedPolicies.get(step.policy);
351	
352	  if (policy === undefined) {
353	    throw new Error(`claim against unknown policy: ${step.policy}`);
354	  }
355	
356	  return policy;
357	};
358	
359	const takeClaimStep = (
360	  step: ClaimStep,
361	  history: ScenarioHistory,
362	): ScenarioHistory => {
363	  const policy = issuedPolicyFor(step, history.issuedPolicies);
364	  const { payout, remainingCap } = settleClaim(step.incident, policy);
365	
366	  return withStepRecorded(history, {
367	    policyIndex: step.policy,
368	    policy: { ...policy, remainingCap },
369	    result: { payout, remainingCap },
370	  });
371	};
372	
373	export const runScenario = (scenario: Scenario): ScenarioResult => {
374	  const history = scenario.steps.reduce(
375	    (soFar, step, stepIndex) =>
376	      isQuote(step)
377	        ? takeQuoteStep(step, stepIndex, soFar, scenario.customer)
378	        : takeClaimStep(step, soFar),
379	    EMPTY_HISTORY,
380	  );
381	
382	  return { results: history.results };
383	};
