3	const readStdin = async (): Promise<string> => {
4	  const chunks: string[] = [];
5	
6	  process.stdin.setEncoding("utf8");
7	  for await (const chunk of process.stdin) {
8	    chunks.push(chunk as string);
9	  }
10	
11	  return chunks.join("");
12	};
13	
14	const resultJsonFor = (scenarioJson: string): string =>
15	  JSON.stringify(runScenario(JSON.parse(scenarioJson) as Scenario));
16	
17	const FAILURE_EXIT_CODE = 1;
18	
19	try {
20	  process.stdout.write(resultJsonFor(await readStdin()));
21	} catch (error) {
22	  process.stderr.write(`${(error as Error).message}\n`);
23	  process.exit(FAILURE_EXIT_CODE);
24	}
